export type SwatchName = "green" | "teal" | "blue" | "violet" | "pink" | "orange" | "graphite";

export interface Swatch {
  name: SwatchName;
  label: string;
  /** Fill for a light surface, and the label colour that meets AA on it. */
  light: string;
  lightInk: string;
  /** Fill for a dark surface. Bright, so the label is near-black, not the theme ink. */
  dark: string;
  darkInk: string;
}

