/** Quota thresholds, as percentages. */
export const THRESHOLDS = {"warn":70,"critical":90} as const;

export type QuotaState = "ok" | "warn" | "critical";

/** The one copy of the rule that used to be written out four times. */
export function quotaState(percent: number): QuotaState {
  if (percent > THRESHOLDS.critical) return "critical";
  if (percent > THRESHOLDS.warn) return "warn";
  return "ok";
}

